+/** Picks a supported language (`en` or `ko`) from an `Accept-Language` header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const choices = [];
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    const lang = rawTag.trim().toLowerCase().split(/[-_]/)[0];
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p.trim());
+      if (m) q = Number(m[1]);
+    }
+    if (LANGUAGES.includes(lang) && Number.isFinite(q) && q > 0 && q <= 1) {
+      choices.push({ lang, q });
+    }
+  }
+  choices.sort((a, b) => b.q - a.q);
+  return choices[0]?.lang ?? fallback;
+}
